<template>
  <div class="login" :class="{ 'login--dark': isDark }">
    <div class="login__field" aria-hidden="true">
      <span v-for="pill in pills" :key="pill" class="login__pill" :class="`login__pill--${pill}`"></span>
    </div>

    <div class="login__toolbar">
      <v-menu location="bottom end">
        <template #activator="{ props }">
          <v-btn
              v-bind="props"
              class="login__chip"
              :prepend-icon="mdiTranslate"
              :aria-label="$t('common.language')"
              variant="flat"
              rounded="pill"
          >
            {{ locale.toUpperCase() }}
          </v-btn>
        </template>
        <v-list density="compact" rounded="lg" class="login__menu">
          <v-list-item
              v-for="item in locales"
              :key="item.code"
              :active="item.code === locale"
              :title="item.title"
              @click="setLocale(item.code)"
          />
        </v-list>
      </v-menu>

      <v-btn
          class="login__chip"
          :icon="isDark ? mdiWeatherSunny : mdiWeatherNight"
          :aria-label="`${$t('common.theme')}: ${$t(`themes.${isDark ? 'light' : 'dark'}`)}`"
          variant="flat"
          @click="toggleTheme"
      />
    </div>

    <main class="login__card">
      <brand-logo class="login__logo" animated/>

      <transition name="login-swap" mode="out-in">
        <section v-if="mode === 'login'" key="login" class="login__panel">
          <h1 class="login__title">{{ $t('auth.title') }}</h1>
          <p class="login__subtitle">{{ $t('auth.subtitle') }}</p>

          <v-form ref="loginForm" class="login__form" @submit.prevent="submitLogin">
            <v-text-field
                v-model="form.login"
                :label="$t('auth.login')"
                :rules="[required]"
                :prepend-inner-icon="mdiAccountOutline"
                autocomplete="username"
                autocapitalize="off"
                spellcheck="false"
                variant="solo-filled"
                flat
                rounded="lg"
                autofocus
            />

            <v-text-field
                v-model="form.password"
                :label="$t('auth.password')"
                :rules="[required]"
                :type="showPassword ? 'text' : 'password'"
                :prepend-inner-icon="mdiLockOutline"
                autocomplete="current-password"
                variant="solo-filled"
                flat
                rounded="lg"
            >
              <template #append-inner>
                <v-btn
                    :icon="showPassword ? mdiEyeOffOutline : mdiEyeOutline"
                    :aria-label="showPassword ? $t('auth.hidePassword') : $t('auth.showPassword')"
                    :aria-pressed="showPassword"
                    variant="text"
                    size="small"
                    density="comfortable"
                    @click="showPassword = !showPassword"
                />
              </template>
            </v-text-field>

            <transition name="login-alert">
              <v-alert
                  v-if="error"
                  :key="errorKey"
                  class="login__alert"
                  type="error"
                  variant="tonal"
                  density="compact"
                  rounded="lg"
                  role="alert"
              >
                {{ errorText }}
              </v-alert>
            </transition>

            <v-btn
                class="login__submit"
                type="submit"
                color="primary"
                size="x-large"
                rounded="pill"
                block
                :loading="loading"
            >
              {{ $t('auth.submit') }}
            </v-btn>
          </v-form>

          <v-btn class="login__link" variant="text" rounded="pill" @click="switchMode('support')">
            {{ $t('auth.forgot') }}
          </v-btn>
        </section>

        <section v-else key="support" class="login__panel">
          <h1 class="login__title">{{ $t('auth.supportTitle') }}</h1>
          <p class="login__subtitle">{{ $t('auth.supportText') }}</p>

          <v-btn
              class="login__submit login__telegram"
              :href="support.TELEGRAM_URL"
              target="_blank"
              rel="noopener noreferrer"
              :prepend-icon="mdiSend"
              size="x-large"
              rounded="pill"
              block
          >
            {{ $t('auth.supportButton') }}
          </v-btn>
          <p class="login__contact">{{ support.TELEGRAM_PHONE }}</p>

          <v-btn
              class="login__link"
              :prepend-icon="mdiArrowLeft"
              variant="text"
              rounded="pill"
              @click="switchMode('login')"
          >
            {{ $t('auth.back') }}
          </v-btn>
        </section>
      </transition>
    </main>
  </div>
</template>

<script>
import {mapActions, mapState} from 'pinia'
import {
  mdiAccountOutline,
  mdiArrowLeft,
  mdiEyeOffOutline,
  mdiEyeOutline,
  mdiLockOutline,
  mdiSend,
  mdiTranslate,
  mdiWeatherNight,
  mdiWeatherSunny,
} from '@mdi/js'
import BrandLogo from '@/components/BrandLogo.vue'
import {SUPPORT} from '@/configurations'
import {useAccessStore} from '@/stores/access'
import {useSettingsStore} from '@/stores/settings'

export default {
  name: 'LoginView',

  components: {
    BrandLogo,
  },

  data() {
    return {
      mode: 'login',
      form: {
        login: '',
        password: '',
      },
      showPassword: false,
      loading: false,
      error: null,
      errorKey: 0,
      support: SUPPORT,
      pills: ['ink-large', 'white', 'ink-small', 'outline', 'white-small'],
      mdiAccountOutline,
      mdiArrowLeft,
      mdiEyeOffOutline,
      mdiEyeOutline,
      mdiLockOutline,
      mdiSend,
      mdiTranslate,
      mdiWeatherNight,
      mdiWeatherSunny,
    }
  },

  computed: {
    ...mapState(useSettingsStore, ['locale', 'locales', 'isDark']),

    errorText() {
      const key = `auth.errors.${this.error}`
      return this.$te(key) ? this.$t(key) : this.$t('auth.errors.server_error')
    },
  },

  methods: {
    ...mapActions(useSettingsStore, ['setLocale', 'toggleTheme']),
    ...mapActions(useAccessStore, ['login']),

    required(value) {
      return (typeof value === 'string' && value.trim() !== '') || this.$t('auth.required')
    },

    showError(error) {
      this.error = (error && error.code) || 'server_error'
      // Новый ключ перезапускает анимацию, даже если ошибка та же
      this.errorKey += 1
    },

    switchMode(mode) {
      this.mode = mode
      this.error = null
    },

    async submitLogin() {
      const {valid} = await this.$refs.loginForm.validate()
      if (!valid || this.loading) return

      this.loading = true
      this.error = null
      try {
        // Переход на нужную страницу после входа делает App.vue (следит за входом)
        await this.login(this.form.login, this.form.password)
      } catch (error) {
        this.showError(error)
      } finally {
        this.loading = false
      }
    },
  },
}
</script>

